    def cargar_datos_db(self):
            cursor=self.con.cursor()
            sql="select * from capitales"
            cursor.execute(sql)
            resultado=cursor.fetchall()
            # Para poner encabezado nombres en la tabla
            columnas = [desc[0] for desc in cursor.description]
            self.tableWidget.setColumnCount(len(columnas))
            self.tableWidget.setRowCount(len(resultado))
            self.tableWidget.setHorizontalHeaderLabels(columnas)
            
            for fila,registro in enumerate(resultado):
                for col,valor in enumerate(registro):
                    texto = "" if valor is None else str(valor)
                    item = QTableWidgetItem(texto)
                    self.tableWidget.setItem(fila,col,item)            
                    
    def filtrar(self):
        cursor=self.con.cursor()
        sql="select * from capitales where Población >= %s AND Población <= %s"
        cursor.execute(sql,(self.lineEdit.text(), self.lineEdit_2.text(),))
        resultado=cursor.fetchall()
        # Para poner encabezado nombres en la tabla
        columnas = [desc[0] for desc in cursor.description]
        self.tableWidget.setColumnCount(len(columnas))
        self.tableWidget.setRowCount(len(resultado))
        self.tableWidget.setHorizontalHeaderLabels(columnas)
        for fila,registro in enumerate(resultado):
            for col,valor in enumerate(registro):
                texto = "" if valor is None else str(valor)
                item = QTableWidgetItem(texto)
                self.tableWidget.setItem(fila,col,item)
            
    
